<?php require __DIR__.'/config.php';try{$types=db()->query('SELECT type_name,minimum_balance,interest_rate FROM account_types ORDER BY type_name')->fetchAll();}catch(Throwable $x){$types=[];$unavailable=true;}render_start('Rates');?><section class="page-heading"><div class="eyebrow dark">Accounts that fit your plans</div><h1>Rates &amp; account options</h1><p>Review the minimum balance and interest rate for each account type.</p></section><?php if(!empty($unavailable)):?><div class="notice error">Account rates are temporarily unavailable. Please try again later.</div><?php elseif(!$types):?><div class="empty">Account options will appear here when available.</div><?php else:?><div class="rate-grid"><?php foreach($types as $t):?><article class="rate-card"><div class="eyebrow dark">BankEase account</div><h2><?=e($t['type_name'])?></h2><div class="rate-number"><?=e(number_format((float)$t['interest_rate'],2))?><span>%</span></div><p>Annual interest rate</p><div class="minimum"><span>Minimum balance</span><b>BDT <?=e(number_format((float)$t['minimum_balance'],2))?></b></div><a class="button navy" href="<?=e(url('register.php'))?>">Apply for account</a></article><?php endforeach;?></div><?php endif;?><p class="footnote">Rates and terms are supplied by BankEase account configuration and may change.</p><?php render_end();?>
